  ('a11y-live-region-toast', 'quiz', 2, 90, '{"en":"Announcing a toast without moving focus","uk":"Оголошення сповіщення без переміщення фокуса"}'::jsonb, '{"en":"After saving, a toast says \"Saved\". Screen reader users should hear it without moving focus. What helps?","uk":"Після збереження спливає повідомлення «Saved». Користувачі екранних читачів мають почути його без переміщення фокуса. Що допоможе?"}'::jsonb, 'web-accessibility', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Changing only the background color of the toast","uk":"Зміна лише кольору фону сповіщення"}},{"id":"b","text":{"en":"Placing the message in a live region, such as `role=\"status\"` or `aria-live=\"polite\"`","uk":"Розміщення повідомлення в live-регіоні, наприклад `role=\"status\"` або `aria-live=\"polite\"`"}},{"id":"c","text":{"en":"A tooltip that appears on hover","uk":"Підказка, що з''являється при наведенні"}},{"id":"d","text":{"en":"Removing the toast from the DOM after 1 ms","uk":"Видалення сповіщення з DOM за 1 мс"}}]}'::jsonb, null::jsonb),
  ('git-reset-soft-keep-staged', 'quiz', 2, 90, '{"en":"Undo a commit but keep its changes staged","uk":"Скасувати коміт, але зберегти зміни в індексі"}'::jsonb, '{"en":"You want to undo the last commit but keep its changes staged. Which command does that?","uk":"Ви хочете скасувати останній коміт, але зберегти його зміни в індексі. Яка команда це робить?"}'::jsonb, 'git', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`git reset --hard HEAD~1`","uk":"`git reset --hard HEAD~1`"}},{"id":"b","text":{"en":"`git reset --soft HEAD~1`","uk":"`git reset --soft HEAD~1`"}},{"id":"c","text":{"en":"`git checkout -- .`","uk":"`git checkout -- .`"}},{"id":"d","text":{"en":"`git revert HEAD` with no other changes","uk":"`git revert HEAD` без інших змін"}}]}'::jsonb, null::jsonb),
  ('js-weakmap-garbage-collection', 'quiz', 2, 90, '{"en":"Storing data per DOM element","uk":"Зберігання даних для кожного DOM-елемента"}'::jsonb, '{"en":"Why use a `WeakMap` keyed by DOM elements to store extra data about them?","uk":"Навіщо використовувати `WeakMap` з ключами-DOM-елементами для зберігання додаткових даних про них?"}'::jsonb, 'js-collections', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"It is faster for string keys","uk":"Він швидший для рядкових ключів"}},{"id":"b","text":{"en":"Its keys are held weakly, so once an element is removed and unreferenced, its entry can be garbage collected","uk":"Його ключі утримуються слабко, тож коли елемент видалено і на нього ніхто не посилається, його запис можна прибрати збирачем сміття"}},{"id":"c","text":{"en":"It persists the data across page reloads","uk":"Він зберігає дані між перезавантаженнями сторінки"}},{"id":"d","text":{"en":"It keeps keys sorted","uk":"Він тримає ключі відсортованими"}}]}'::jsonb, null::jsonb),
  ('ig-iterable', 'quiz', 1, 45, '{"en":"What makes an object iterable","uk":"Що робить об''єкт ітерованим"}'::jsonb, '{"en":"What must an object have so that `for…of` and `[...obj]` work with it?","uk":"Що повинен мати об''єкт, щоб із ним працювали `for…of` і `[...obj]`?"}'::jsonb, 'iterators-generators', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"A `[Symbol.iterator]()` method that returns an iterator (an object with `next()` returning `{ value, done }`)","uk":"Метод `[Symbol.iterator]()`, що повертає ітератор (об''єкт з `next()`, який повертає `{ value, done }`)"}},{"id":"b","text":{"en":"A `length` property","uk":"Властивість `length`"}},{"id":"c","text":{"en":"A `forEach` method","uk":"Метод `forEach`"}},{"id":"d","text":{"en":"Numeric keys starting at 0","uk":"Числові ключі, що починаються з 0"}}]}'::jsonb, null::jsonb),
  ('ig-lazy-start', 'quiz', 2, 90, '{"en":"When a generator body runs","uk":"Коли виконується тіло генератора"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"function* gen() {\n  console.log(\"start\");\n  yield 1;\n  console.log(\"after 1\");\n  yield 2;\n}\nconst it = gen();\nconsole.log(\"created\");\nconsole.log(it.next().value);\nconsole.log(it.next().value);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`created`, `start`, `1`, `after 1`, `2`","uk":"`created`, `start`, `1`, `after 1`, `2`"}},{"id":"b","text":{"en":"`start`, `created`, `1`, `after 1`, `2`","uk":"`start`, `created`, `1`, `after 1`, `2`"}},{"id":"c","text":{"en":"`start`, `after 1`, `created`, `1`, `2`","uk":"`start`, `after 1`, `created`, `1`, `2`"}},{"id":"d","text":{"en":"`created`, `1`, `2`, `start`, `after 1`","uk":"`created`, `1`, `2`, `start`, `after 1`"}}]}'::jsonb, null::jsonb),
  ('ig-next-value', 'quiz', 2, 90, '{"en":"Sending values into a generator","uk":"Передача значень у генератор"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"function* adder() {\n  const a = yield \"first?\";\n  const b = yield \"second?\";\n  return a + b;\n}\nconst it = adder();\nconsole.log(it.next(10).value, it.next(2).value, it.next(3).value);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`first? second? 5`","uk":"`first? second? 5`"}},{"id":"b","text":{"en":"`first? second? 12`","uk":"`first? second? 12`"}},{"id":"c","text":{"en":"`first? second? 13`","uk":"`first? second? 13`"}},{"id":"d","text":{"en":"`10 2 3`","uk":"`10 2 3`"}}]}'::jsonb, null::jsonb),
  ('ig-return-value', 'quiz', 3, 90, '{"en":"Where the return value goes","uk":"Куди потрапляє повернене значення"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"function* g() {\n  yield 1;\n  yield 2;\n  return 3;\n}\nconsole.log([...g()], Array.from(g()).length);\nconst it = g();\nit.next();\nit.next();\nconsole.log(it.next());","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ 1, 2 ] 2`, then `{ value: 3, done: true }`","uk":"`[ 1, 2 ] 2`, потім `{ value: 3, done: true }`"}},{"id":"b","text":{"en":"`[ 1, 2, 3 ] 3`, then `{ value: undefined, done: true }`","uk":"`[ 1, 2, 3 ] 3`, потім `{ value: undefined, done: true }`"}},{"id":"c","text":{"en":"`[ 1, 2 ] 2`, then `{ value: undefined, done: true }`","uk":"`[ 1, 2 ] 2`, потім `{ value: undefined, done: true }`"}},{"id":"d","text":{"en":"`[ 1, 2, 3 ] 3`, then `{ value: 3, done: true }`","uk":"`[ 1, 2, 3 ] 3`, потім `{ value: 3, done: true }`"}}]}'::jsonb, null::jsonb),
  ('ig-yield-star', 'quiz', 3, 90, '{"en":"Delegating with `yield*`","uk":"Делегування через `yield*`"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"function* inner() {\n  yield \"a\";\n  return \"r\";\n}\nfunction* outer() {\n  const r = yield* inner();\n  yield r;\n  yield* [1, 2];\n}\nconsole.log([...outer()]);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''a'', ''r'', 1, 2 ]`","uk":"`[ ''a'', ''r'', 1, 2 ]`"}},{"id":"b","text":{"en":"`[ ''a'', 1, 2 ]`","uk":"`[ ''a'', 1, 2 ]`"}},{"id":"c","text":{"en":"`[ ''a'', ''r'', [ 1, 2 ] ]`","uk":"`[ ''a'', ''r'', [ 1, 2 ] ]`"}},{"id":"d","text":{"en":"`[ ''a'', undefined, 1, 2 ]`","uk":"`[ ''a'', undefined, 1, 2 ]`"}}]}'::jsonb, null::jsonb),
  ('ig-for-await', 'quiz', 3, 90, '{"en":"Async generators","uk":"Асинхронні генератори"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"async function* pages() {\n  for (let p = 1; p <= 3; p++) {\n    await new Promise((r) => setTimeout(r, 5));\n    yield [p * 10, p * 10 + 1];\n  }\n}\nconst all = [];\nfor await (const page of pages()) all.push(...page);\nconsole.log(all);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ 10, 11, 20, 21, 30, 31 ]`","uk":"`[ 10, 11, 20, 21, 30, 31 ]`"}},{"id":"b","text":{"en":"`[ [ 10, 11 ], [ 20, 21 ], [ 30, 31 ] ]`","uk":"`[ [ 10, 11 ], [ 20, 21 ], [ 30, 31 ] ]`"}},{"id":"c","text":{"en":"`[]`, because the loop finishes before the timers","uk":"`[]`, бо цикл завершується раніше за таймери"}},{"id":"d","text":{"en":"`[ Promise, Promise, Promise ]`","uk":"`[ Promise, Promise, Promise ]`"}}]}'::jsonb, null::jsonb),
  ('ig-break-closes', 'quiz', 4, 120, '{"en":"Breaking out of a loop","uk":"Вихід із циклу через break"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"function* nums() {\n  yield 1;\n  yield 2;\n  yield 3;\n}\nconst g = nums();\nfor (const x of g) break;\n\nconst a = [1, 2, 3][Symbol.iterator]();\nfor (const x of a) break;\n\nconsole.log([...g], [...a]);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[] [ 2, 3 ]`","uk":"`[] [ 2, 3 ]`"}},{"id":"b","text":{"en":"`[ 2, 3 ] [ 2, 3 ]`","uk":"`[ 2, 3 ] [ 2, 3 ]`"}},{"id":"c","text":{"en":"`[] []`","uk":"`[] []`"}},{"id":"d","text":{"en":"`[ 1, 2, 3 ] [ 1, 2, 3 ]`","uk":"`[ 1, 2, 3 ] [ 1, 2, 3 ]`"}}]}'::jsonb, null::jsonb),
  ('ig-finally-cleanup', 'quiz', 4, 90, '{"en":"Cleanup on early exit","uk":"Очищення при достроковому виході"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"function* resource() {\n  try {\n    yield 1;\n    yield 2;\n  } finally {\n    console.log(\"cleanup\");\n  }\n}\nfor (const x of resource()) {\n  console.log(x);\n  break;\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`1`, then `cleanup`","uk":"`1`, потім `cleanup`"}},{"id":"b","text":{"en":"Only `1`","uk":"Лише `1`"}},{"id":"c","text":{"en":"`1`, `2`, then `cleanup`","uk":"`1`, `2`, потім `cleanup`"}},{"id":"d","text":{"en":"`cleanup`, then `1`","uk":"`cleanup`, потім `1`"}}]}'::jsonb, null::jsonb),
  ('ig-coroutine-runner', 'quiz', 4, 150, '{"en":"Generators before async/await","uk":"Генератори до async/await"}'::jsonb, '{"en":"What does this print, and what modern feature does `run` imitate?","uk":"Що виведе цей код і яку сучасну можливість імітує `run`?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"function run(gen) {\n  const it = gen();\n  return new Promise((resolve, reject) => {\n    function step(value) {\n      const r = it.next(value);\n      if (r.done) return resolve(r.value);\n      Promise.resolve(r.value).then(step, reject);\n    }\n    step();\n  });\n}\nrun(function* () {\n  const a = yield Promise.resolve(2);\n  const b = yield 3;\n  return a * b;\n}).then(console.log);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`6`; `async`/`await`, where `yield` plays the role of `await`","uk":"`6`; `async`/`await`, де `yield` грає роль `await`"}},{"id":"b","text":{"en":"`NaN`; `Promise.all`","uk":"`NaN`; `Promise.all`"}},{"id":"c","text":{"en":"`[Promise, 3]`; `Promise.race`","uk":"`[Promise, 3]`; `Promise.race`"}},{"id":"d","text":{"en":"Nothing; generators can''t yield promises","uk":"Нічого; генератори не можуть видавати проміси"}}]}'::jsonb, null::jsonb),
  ('ig-throw-into', 'quiz', 5, 150, '{"en":"Throwing into a generator","uk":"Кидання помилки в генератор"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'iterators-generators', '{"mode":"single","code":"function* g() {\n  try {\n    yield 1;\n  } catch (e) {\n    yield \"caught \" + e;\n  }\n  yield 3;\n}\nconst it = g();\nconsole.log(it.next().value, it.throw(\"boom\").value, it.next().value, it.next().done);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`1 caught boom 3 true`","uk":"`1 caught boom 3 true`"}},{"id":"b","text":{"en":"`1 undefined 3 false`","uk":"`1 undefined 3 false`"}},{"id":"c","text":{"en":"It throws `boom` at the caller","uk":"Кидає `boom` викликачу"}},{"id":"d","text":{"en":"`1 caught boom undefined true`","uk":"`1 caught boom undefined true`"}}]}'::jsonb, null::jsonb),
  ('ig-lazy-pipeline', 'practice', 3, 1080, '{"en":"Lazy iterator helpers","uk":"Ліниві помічники для ітераторів"}'::jsonb, '{"en":"Write lazy, generator-based helpers in `src/lazy.ts` that work with **any iterable**, including infinite ones:\n\n- `range(start = 0, end = Infinity, step = 1)`: counts up or down (negative step), end exclusive; throws a `RangeError` for a zero step.\n- `map(iterable, fn)` and `filter(iterable, pred)`: the callbacks also receive the index.\n- `take(iterable, n)`: the first `n` values, pulling **exactly** `n` from the source (not one more) and none for `n <= 0`.\n- `chunk(iterable, size)`: arrays of `size`, plus the final shorter one; `RangeError` for sizes below 1.\n- `zip(a, b)`: pairs `[a, b]`, stopping at the shorter input and **closing** the other iterator (call its `return()`) so it can clean up.\n\nNothing may be computed before it''s requested.","uk":"Напишіть ліниві помічники на генераторах у `src/lazy.ts`, що працюють з **будь-якими ітерованими об''єктами**, зокрема нескінченними:\n\n- `range(start = 0, end = Infinity, step = 1)`: рахує вгору чи вниз (від''ємний крок), кінець не включно; для нульового кроку кидає `RangeError`.\n- `map(iterable, fn)` і `filter(iterable, pred)`: колбеки отримують також індекс.\n- `take(iterable, n)`: перші `n` значень, беручи з джерела **рівно** `n` (не більше) і жодного для `n <= 0`.\n- `chunk(iterable, size)`: масиви розміру `size` плюс останній коротший; `RangeError` для розмірів менше 1.\n- `zip(a, b)`: пари `[a, b]`, зупиняючись на коротшому вході й **закриваючи** інший ітератор (викликом його `return()`), щоб він міг прибрати за собою.\n\nНічого не повинно обчислюватися раніше, ніж його попросять."}'::jsonb, 'iterators-generators', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/lazy.ts":"/** start, start + step, … while before end (end is exclusive; negative steps count down). */\nexport function* range(start = 0, end = Infinity, step = 1): Generator<number> {\n  // TODO: negative steps, and a RangeError for step 0\n  for (let x = start; x < end; x += step) yield x;\n}\n\nexport function* map<T, U>(iterable: Iterable<T>, fn: (value: T, index: number) => U): Generator<U> {\n  // TODO: pass the index too\n  for (const x of iterable) yield (fn as (value: T) => U)(x);\n}\n\nexport function* filter<T>(iterable: Iterable<T>, pred: (value: T, index: number) => boolean): Generator<T> {\n  for (const x of iterable) if ((pred as (value: T) => boolean)(x)) yield x;\n}\n\nexport function* take<T>(iterable: Iterable<T>, n: number): Generator<T> {\n  // TODO: this pulls one value too many from the source\n  let count = 0;\n  for (const x of iterable) {\n    if (count++ >= n) return;\n    yield x;\n  }\n}\n\nexport function* chunk<T>(iterable: Iterable<T>, size: number): Generator<T[]> {\n  // TODO: the last, shorter chunk is lost; validate size\n  let buffer: T[] = [];\n  for (const x of iterable) {\n    buffer.push(x);\n    if (buffer.length === size) {\n      yield buffer;\n      buffer = [];\n    }\n  }\n}\n\nexport function* zip<A, B>(a: Iterable<A>, b: Iterable<B>): Generator<[A, B]> {\n  // TODO: close the other iterator when one runs out\n  const ib = b[Symbol.iterator]();\n  for (const x of a) {\n    const r = ib.next();\n    if (r.done) return;\n    yield [x, r.value];\n  }\n}\n","/index.ts":"import \"./styles.css\";\nimport { filter, map, range, take } from \"./src/lazy\";\n\n// The first five odd squares, from an infinite sequence: only what''s needed is computed.\nconst result = [...take(filter(map(range(1), (x) => x * x), (x) => x % 2 === 1), 5)];\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Lazy pipeline</h1><p><output id=\"out\">'' + result.join(\", \") + \"</output></p>\";\n"},"visibleFiles":["/src/lazy.ts","/index.ts"],"activeFile":"/src/lazy.ts","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { chunk, filter, map, range, take, zip } from \"../src/lazy\";\n\nfunction counted(values) {\n  const stats = { pulled: 0, closed: false };\n  function* gen() {\n    try {\n      for (const v of values) { stats.pulled++; yield v; }\n    } finally {\n      stats.closed = true;\n    }\n  }\n  return { gen: gen(), stats };\n}\n\ndescribe(\"range\", () => {\n  it(\"counts up, down and forever\", () => {\n    expect([...range(1, 10, 3)]).toEqual([1, 4, 7]);\n    expect([...range(5, 0, -2)]).toEqual([5, 3, 1]);\n    expect([...take(range(), 3)]).toEqual([0, 1, 2]);\n  });\n  it(\"rejects a zero step\", () => {\n    expect(() => range(0, 1, 0).next()).toThrow(RangeError);\n  });\n});\n\ndescribe(\"map and filter\", () => {\n  it(\"pass the index and work on any iterable\", () => {\n    expect([...map([\"a\", \"b\"], (x, i) => x + i)]).toEqual([\"a0\", \"b1\"]);\n    expect([...filter(new Set([5, 6, 7]), (x, i) => i !== 1)]).toEqual([5, 7]);\n    expect([...map(\"hi\", (c) => c.toUpperCase())]).toEqual([\"H\", \"I\"]);\n  });\n});\n\ndescribe(\"take\", () => {\n  it(\"is lazy: pulls exactly n values and calls the mapper n times\", () => {\n    const { gen, stats } = counted([1, 2, 3, 4, 5]);\n    let calls = 0;\n    const out = [...take(map(gen, (x) => { calls++; return x * 10; }), 2)];\n    expect(out).toEqual([10, 20]);\n    expect(stats.pulled).toBe(2);\n    expect(calls).toBe(2);\n    expect(stats.closed).toBe(true);\n  });\n  it(\"doesn''t start the source for n = 0\", () => {\n    const { gen, stats } = counted([1, 2]);\n    expect([...take(gen, 0)]).toEqual([]);\n    expect(stats.pulled).toBe(0);\n  });\n  it(\"handles infinite pipelines\", () => {\n    expect([...take(filter(map(range(1), (x) => x * x), (x) => x % 2 === 1), 3)]).toEqual([1, 9, 25]);\n  });\n});\n\ndescribe(\"chunk\", () => {\n  it(\"groups values and keeps the last partial chunk\", () => {\n    expect([...chunk(range(0, 7), 3)]).toEqual([[0, 1, 2], [3, 4, 5], [6]]);\n    expect([...chunk([], 2)]).toEqual([]);\n  });\n  it(\"rejects invalid sizes\", () => {\n    expect(() => chunk([1], 0).next()).toThrow(RangeError);\n  });\n});\n\ndescribe(\"zip\", () => {\n  it(\"pairs values and stops at the shorter input\", () => {\n    expect([...zip([1, 2, 3], \"ab\")]).toEqual([[1, \"a\"], [2, \"b\"]]);\n  });\n  it(\"closes the other iterator when one runs out\", () => {\n    const { gen, stats } = counted([\"x\", \"y\", \"z\"]);\n    expect([...zip([1, 2], gen)]).toEqual([[1, \"x\"], [2, \"y\"]]);\n    expect(stats.closed).toBe(true);\n  });\n  it(\"renders the demo\", async () => {\n    expect((await screen.findByText(\"1, 9, 25, 49, 81\")).id).toBe(\"out\");\n  });\n});\n","testCount":11}'::jsonb),
  ('ig-coroutine', 'practice', 4, 1200, '{"en":"Build async/await from generators","uk":"Створіть async/await з генераторів"}'::jsonb, '{"en":"Before `async`/`await`, libraries like `co` ran generators as coroutines. Implement `run(genFn, ...args)` in `src/run.ts`:\n\n- Call `genFn(...args)` and drive the generator; return a promise of its **return value**.\n- Whenever it yields a promise (or any value), wait for it and resume the generator with the result via `next(result)`.\n- If a yielded promise rejects, **throw the error into the generator** with `throw(error)`, so `try/catch` inside it works; if the generator doesn''t catch it, `run` rejects.\n- A yielded **array** waits for all of its items in parallel (like `Promise.all`) and sends back the array of results.\n- Errors thrown synchronously by the generator (even before its first `yield`) must reject the promise, never throw from `run` itself.","uk":"До появи `async`/`await` бібліотеки на кшталт `co` виконували генератори як корутини. Реалізуйте `run(genFn, ...args)` у `src/run.ts`:\n\n- Викличте `genFn(...args)` і керуйте генератором; поверніть проміс його **поверненого значення**.\n- Щоразу, коли він видає проміс (або будь-яке значення), дочекайтеся його й продовжте генератор із результатом через `next(result)`.\n- Якщо виданий проміс відхиляється, **киньте помилку в генератор** через `throw(error)`, щоб усередині працював `try/catch`; якщо генератор її не перехопив, `run` відхиляється.\n- Виданий **масив** чекає на всі свої елементи паралельно (як `Promise.all`) і повертає масив результатів.\n- Помилки, які генератор кидає синхронно (навіть до першого `yield`), мають відхиляти проміс, а не кидатися з самого `run`."}'::jsonb, 'iterators-generators', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/run.ts":"/**\n * Runs a generator as a coroutine: yielded promises are awaited and their results sent back\n * with next(); rejections are thrown into the generator. Resolves with its return value.\n */\nexport function run<T>(genFn: (...args: any[]) => Generator<unknown, T, any>, ...args: unknown[]): Promise<T> {\n  // TODO: this doesn''t wait for anything\n  const it = genFn(...args);\n  let result = it.next();\n  while (!result.done) result = it.next(result.value);\n  return Promise.resolve(result.value);\n}\n","/index.ts":"import \"./styles.css\";\nimport { run } from \"./src/run\";\n\nconst delay = <T,>(ms: number, value: T) => new Promise<T>((r) => setTimeout(() => r(value), ms));\n\nrun(function* () {\n  const user: { name: string } = yield delay(20, { name: \"Ada\" });\n  const [posts, followers]: number[] = yield [delay(20, 12), delay(20, 340)];\n  return user.name + \": \" + posts + \" posts, \" + followers + \" followers\";\n}).then(\n  (text) => (document.getElementById(\"app\")!.innerHTML = ''<h1>Coroutine</h1><p><output id=\"out\">'' + text + \"</output></p>\"),\n  (e) => (document.getElementById(\"app\")!.textContent = \"error: \" + e.message),\n);\n"},"visibleFiles":["/src/run.ts","/index.ts"],"activeFile":"/src/run.ts","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { run } from \"../src/run\";\n\nconst sleep = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));\nconst fail = (msg) => {\n  const p = Promise.reject(new Error(msg));\n  p.catch(() => {});\n  return p;\n};\n\ndescribe(\"run\", () => {\n  it(\"waits for yielded promises and resolves with the return value\", async () => {\n    const result = await run(function* () {\n      const a = yield Promise.resolve(2);\n      const b = yield 3;\n      return a * b;\n    });\n    expect(result).toBe(6);\n  });\n  it(\"passes arguments to the generator\", async () => {\n    expect(await run(function* (x, y) { return (yield sleep(5, x)) + y; }, 40, 2)).toBe(42);\n  });\n  it(\"runs steps in order\", async () => {\n    const log = [];\n    await run(function* () {\n      log.push(yield sleep(15, \"slow\"));\n      log.push(yield sleep(1, \"fast\"));\n    });\n    expect(log).toEqual([\"slow\", \"fast\"]);\n  });\n  it(\"throws rejections into the generator, where try/catch works\", async () => {\n    const result = await run(function* () {\n      try {\n        yield fail(\"boom\");\n        return \"not reached\";\n      } catch (e) {\n        return \"recovered: \" + e.message;\n      }\n    });\n    expect(result).toBe(\"recovered: boom\");\n  });\n  it(\"rejects when the generator doesn''t handle an error\", async () => {\n    await expect(run(function* () { yield fail(\"unhandled\"); })).rejects.toThrow(\"unhandled\");\n  });\n  it(\"turns a synchronous throw into a rejection\", async () => {\n    let p;\n    expect(() => { p = run(function* () { throw new Error(\"early\"); }); }).not.toThrow();\n    await expect(p).rejects.toThrow(\"early\");\n  });\n  it(\"waits for yielded arrays in parallel\", async () => {\n    const start = Date.now();\n    const result = await run(function* () { return yield [sleep(30, \"a\"), sleep(30, \"b\")]; });\n    expect(result).toEqual([\"a\", \"b\"]);\n    expect(Date.now() - start < 55).toBe(true);\n  });\n  it(\"renders the demo\", async () => {\n    expect((await screen.findByText(\"Ada: 12 posts, 340 followers\")).id).toBe(\"out\");\n  });\n});\n","testCount":8}'::jsonb),
  ('js-nan-includes', 'quiz', 3, 60, '{"en":"Finding NaN","uk":"Пошук NaN"}'::jsonb, '{"en":"What does this log?","uk":"Що буде виведено?"}'::jsonb, 'javascript', '{"mode":"single","code":"const values = [1, NaN, 3];\nconsole.log(values.includes(NaN), values.indexOf(NaN));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`true -1`","uk":"`true -1`"}},{"id":"b","text":{"en":"`true 0`","uk":"`true 0`"}},{"id":"c","text":{"en":"`false -1`","uk":"`false -1`"}},{"id":"d","text":{"en":"`false 0`","uk":"`false 0`"}}]}'::jsonb, null::jsonb),
  ('js-key-order', 'quiz', 4, 75, '{"en":"Property order","uk":"Порядок властивостей"}'::jsonb, '{"en":"What does `Object.keys` return here?","uk":"Що поверне `Object.keys` тут?"}'::jsonb, 'javascript', '{"mode":"single","code":"const scores = { b: 1, 2: 1, a: 1, 1: 1 };\nconsole.log(Object.keys(scores));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[\"b\", \"2\", \"a\", \"1\"]`","uk":"`[\"b\", \"2\", \"a\", \"1\"]`"}},{"id":"b","text":{"en":"`[\"1\", \"2\", \"b\", \"a\"]`","uk":"`[\"1\", \"2\", \"b\", \"a\"]`"}},{"id":"c","text":{"en":"`[\"a\", \"b\", \"1\", \"2\"]`","uk":"`[\"a\", \"b\", \"1\", \"2\"]`"}},{"id":"d","text":{"en":"The order is not specified","uk":"Порядок не визначено"}}]}'::jsonb, null::jsonb),
  ('js-structured-clone', 'quiz', 5, 120, '{"en":"structuredClone limits","uk":"Межі structuredClone"}'::jsonb, '{"en":"Which statements about `structuredClone(value)` are true? Select all that apply.","uk":"Які твердження про `structuredClone(value)` правдиві? Оберіть усі правильні."}'::jsonb, 'javascript', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"It deep-copies `Map`, `Set` and `Date` values","uk":"Глибоко копіює значення `Map`, `Set` і `Date`"}},{"id":"b","text":{"en":"Class instances keep their prototype, so methods still work","uk":"Екземпляри класів зберігають прототип, тож методи працюють"}},{"id":"c","text":{"en":"It throws when the value contains a function","uk":"Кидає помилку, якщо значення містить функцію"}},{"id":"d","text":{"en":"It preserves circular references","uk":"Зберігає циклічні посилання"}}]}'::jsonb, null::jsonb),
  ('js-deep-equal', 'practice', 3, 900, '{"en":"Implement deepEqual","uk":"Реалізуйте deepEqual"}'::jsonb, '{"en":"Implement `deepEqual(a, b)`, which compares two values structurally.\n\n- Primitives are equal when `Object.is` says so (so `NaN` equals `NaN`).\n- Arrays are equal when they have the same length and equal items. An array never equals a plain object.\n- Plain objects are equal when they have the same own keys, in any order, with equal values. `{ a: undefined }` does **not** equal `{}`.\n- `Date` objects are equal when they hold the same time.","uk":"Реалізуйте `deepEqual(a, b)`, що порівнює два значення за структурою.\n\n- Примітиви рівні, якщо так каже `Object.is` (тож `NaN` дорівнює `NaN`).\n- Масиви рівні, якщо мають однакову довжину й рівні елементи. Масив ніколи не дорівнює звичайному об''єкту.\n- Звичайні об''єкти рівні, якщо мають однакові власні ключі в будь-якому порядку з рівними значеннями. `{ a: undefined }` **не** дорівнює `{}`.\n- Об''єкти `Date` рівні, якщо містять той самий час."}'::jsonb, 'javascript', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/deep-equal.ts":"export function deepEqual(a: unknown, b: unknown): boolean {\n  // TODO: compare arrays, plain objects and dates structurally\n  return a === b;\n}\n","/index.ts":"import \"./styles.css\";\nimport { deepEqual } from \"./src/deep-equal\";\n\nconst cases: [unknown, unknown][] = [\n  [{ a: [1, 2] }, { a: [1, 2] }],\n  [{ a: 1 }, { a: 2 }],\n];\ndocument.getElementById(\"app\")!.innerHTML =\n  \"<h1>deepEqual</h1><ul>\" + cases.map(([a, b]) => \"<li>\" + JSON.stringify(a) + \" vs \" + JSON.stringify(b) + \": \" + deepEqual(a, b) + \"</li>\").join(\"\") + \"</ul>\";\n"},"visibleFiles":["/src/deep-equal.ts","/index.ts"],"activeFile":"/src/deep-equal.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { deepEqual } from \"../src/deep-equal\";\n\ndescribe(\"deepEqual\", () => {\n  it(\"compares primitives with Object.is\", () => {\n    expect(deepEqual(1, 1)).toBe(true);\n    expect(deepEqual(\"a\", \"b\")).toBe(false);\n    expect(deepEqual(NaN, NaN)).toBe(true);\n    expect(deepEqual(null, undefined)).toBe(false);\n  });\n  it(\"compares nested arrays and objects\", () => {\n    expect(deepEqual({ a: [1, { b: 2 }] }, { a: [1, { b: 2 }] })).toBe(true);\n    expect(deepEqual({ a: [1, { b: 2 }] }, { a: [1, { b: 3 }] })).toBe(false);\n  });\n  it(\"ignores key order\", () => {\n    expect(deepEqual({ a: 1, b: 2 }, { b: 2, a: 1 })).toBe(true);\n  });\n  it(\"checks array length\", () => {\n    expect(deepEqual([1, 2], [1, 2, 3])).toBe(false);\n  });\n  it(\"never treats an array as an object\", () => {\n    expect(deepEqual([1], { 0: 1 })).toBe(false);\n  });\n  it(\"treats a missing key differently from undefined\", () => {\n    expect(deepEqual({ a: undefined }, {})).toBe(false);\n    expect(deepEqual({}, { a: undefined })).toBe(false);\n  });\n  it(\"compares dates by time\", () => {\n    expect(deepEqual(new Date(0), new Date(0))).toBe(true);\n    expect(deepEqual(new Date(0), new Date(1))).toBe(false);\n    expect(deepEqual(new Date(0), {})).toBe(false);\n  });\n});\n","testCount":7}'::jsonb),
  ('js-typeof-null', 'quiz', 1, 45, '{"en":"typeof null","uk":"typeof null"}'::jsonb, '{"en":"What does `typeof null` return?","uk":"Що повертає `typeof null`?"}'::jsonb, 'javascript', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`\"null\"`","uk":"`\"null\"`"}},{"id":"b","text":{"en":"`\"object\"`","uk":"`\"object\"`"}},{"id":"c","text":{"en":"`\"undefined\"`","uk":"`\"undefined\"`"}},{"id":"d","text":{"en":"It throws a TypeError","uk":"Кидає TypeError"}}]}'::jsonb, null::jsonb),
  ('js-reference-equality', 'quiz', 1, 60, '{"en":"Comparing objects","uk":"Порівняння об''єктів"}'::jsonb, '{"en":"What does this code log?","uk":"Що виведе цей код?"}'::jsonb, 'javascript', '{"mode":"single","code":"const a = { id: 1 };\nconst b = { id: 1 };\nconst c = a;\nconsole.log(a === b, a === c);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`true true`","uk":"`true true`"}},{"id":"b","text":{"en":"`false true`","uk":"`false true`"}},{"id":"c","text":{"en":"`false false`","uk":"`false false`"}},{"id":"d","text":{"en":"`true false`","uk":"`true false`"}}]}'::jsonb, null::jsonb),
  ('js-falsy-values', 'quiz', 2, 90, '{"en":"Falsy values","uk":"Хибні значення"}'::jsonb, '{"en":"Which of these values are **falsy**? Select all that apply.","uk":"Які з цих значень є **хибними (falsy)**? Оберіть усі правильні."}'::jsonb, 'javascript', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`0`","uk":"`0`"}},{"id":"b","text":{"en":"`\"0\"`","uk":"`\"0\"`"}},{"id":"c","text":{"en":"`[]`","uk":"`[]`"}},{"id":"d","text":{"en":"`NaN`","uk":"`NaN`"}},{"id":"e","text":{"en":"`\"\"`","uk":"`\"\"`"}}]}'::jsonb, null::jsonb),
  ('js-this-callback', 'quiz', 3, 120, '{"en":"Lost `this`","uk":"Втрачений `this`"}'::jsonb, '{"en":"What happens when `setTimeout` calls `counter.inc` after 0 ms in strict mode?","uk":"Що станеться, коли `setTimeout` викличе `counter.inc` через 0 мс у strict mode?"}'::jsonb, 'javascript', '{"mode":"single","code":"\"use strict\";\nconst counter = {\n  count: 0,\n  inc() { this.count++; },\n};\nsetTimeout(counter.inc, 0);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`count` becomes 1","uk":"`count` стане 1"}},{"id":"b","text":{"en":"A TypeError is thrown because `this` is `undefined`","uk":"Буде TypeError, бо `this` дорівнює `undefined`"}},{"id":"c","text":{"en":"`count` becomes `NaN`","uk":"`count` стане `NaN`"}},{"id":"d","text":{"en":"Nothing, `setTimeout` ignores methods","uk":"Нічого, `setTimeout` ігнорує методи"}}]}'::jsonb, null::jsonb),
  ('js-prototype-lookup', 'quiz', 4, 150, '{"en":"Prototype chain","uk":"Ланцюжок прототипів"}'::jsonb, '{"en":"What does the last line log?","uk":"Що виведе останній рядок?"}'::jsonb, 'javascript', '{"mode":"single","code":"const base = { kind: \"base\" };\nconst child = Object.create(base);\nchild.kind = \"own\";\ndelete child.kind;\nconsole.log(child.kind);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`\"base\"`","uk":"`\"base\"`"}},{"id":"b","text":{"en":"`\"own\"`","uk":"`\"own\"`"}},{"id":"c","text":{"en":"`undefined`","uk":"`undefined`"}},{"id":"d","text":{"en":"It throws","uk":"Кидає помилку"}}]}'::jsonb, null::jsonb),
  ('js-group-by', 'practice', 2, 600, '{"en":"Implement groupBy","uk":"Реалізуйте groupBy"}'::jsonb, '{"en":"Implement `groupBy(items, keyFn)`. It returns a plain object whose keys are the results of `keyFn(item)` and whose values are arrays of items with that key, **in their original order**. Don''t mutate `items`.\n\n```js\ngroupBy([1.2, 1.7, 2.3], Math.floor) // { 1: [1.2, 1.7], 2: [2.3] }\n```","uk":"Реалізуйте `groupBy(items, keyFn)`. Функція повертає звичайний об''єкт, ключі якого є результатами `keyFn(item)`, а значення є масивами елементів із цим ключем **у початковому порядку**. Не змінюйте `items`.\n\n```js\ngroupBy([1.2, 1.7, 2.3], Math.floor) // { 1: [1.2, 1.7], 2: [2.3] }\n```"}'::jsonb, 'javascript', null::jsonb, '{"framework":"vanilla-js","files":{"/src/groupBy.js":"/**\n * @template T\n * @param {T[]} items\n * @param {(item: T) => string | number} keyFn\n * @returns {Record<string, T[]>}\n */\nexport function groupBy(items, keyFn) {\n  // TODO\n  return {};\n}\n","/index.js":"import \"./styles.css\";\nimport { groupBy } from \"./src/groupBy\";\n\nconst people = [\n  { name: \"Ada\", team: \"core\" },\n  { name: \"Linus\", team: \"infra\" },\n  { name: \"Grace\", team: \"core\" },\n];\nconst groups = groupBy(people, (p) => p.team);\n\ndocument.getElementById(\"app\").innerHTML =\n  \"<h1>Teams</h1>\" +\n  Object.entries(groups)\n    .map(([team, list]) => `<h2>${team}</h2><ul>${list.map((p) => `<li>${p.name}</li>`).join(\"\")}</ul>`)\n    .join(\"\");\n"},"visibleFiles":["/src/groupBy.js","/index.js"],"activeFile":"/src/groupBy.js","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { groupBy } from \"../src/groupBy\";\n\ndescribe(\"groupBy\", () => {\n  it(\"groups by the key function\", () => {\n    expect(groupBy([1.2, 1.7, 2.3], Math.floor)).toEqual({ 1: [1.2, 1.7], 2: [2.3] });\n  });\n  it(\"keeps the original order inside groups\", () => {\n    const words = [\"apple\", \"bob\", \"avocado\", \"banana\"];\n    expect(groupBy(words, (w) => w[0])).toEqual({ a: [\"apple\", \"avocado\"], b: [\"bob\", \"banana\"] });\n  });\n  it(\"returns an empty object for an empty array\", () => expect(groupBy([], (x) => x)).toEqual({}));\n  it(\"does not mutate the input\", () => {\n    const input = [3, 1, 2];\n    groupBy(input, (n) => n % 2);\n    expect(input).toEqual([3, 1, 2]);\n  });\n  it(\"renders the teams demo\", async () => {\n    await screen.findByRole(\"heading\", { name: \"core\" });\n    expect(screen.getAllByRole(\"listitem\")).toHaveLength(3);\n  });\n});\n","testCount":5}'::jsonb),
  ('cls-tdz', 'quiz', 1, 45, '{"en":"Using a class before its declaration","uk":"Використання класу до його оголошення"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"try {\n  new Foo();\n} catch (e) {\n  console.log(e.constructor.name);\n}\nclass Foo {}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`ReferenceError`","uk":"`ReferenceError`"}},{"id":"b","text":{"en":"`TypeError`","uk":"`TypeError`"}},{"id":"c","text":{"en":"Nothing: the class is hoisted, so `new Foo()` works","uk":"Нічого: клас спливає, тож `new Foo()` працює"}},{"id":"d","text":{"en":"`SyntaxError`","uk":"`SyntaxError`"}}]}'::jsonb, null::jsonb),
  ('cls-methods-not-enumerable', 'quiz', 2, 60, '{"en":"Where do class members live?","uk":"Де живуть члени класу?"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class Point {\n  constructor() {\n    this.x = 1;\n  }\n  move() {}\n}\nconst keys = [];\nfor (const k in new Point()) keys.push(k);\nconsole.log(keys, typeof Point);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''x'' ] function`","uk":"`[ ''x'' ] function`"}},{"id":"b","text":{"en":"`[ ''x'', ''move'' ] function`","uk":"`[ ''x'', ''move'' ] function`"}},{"id":"c","text":{"en":"`[ ''x'', ''move'' ] object`","uk":"`[ ''x'', ''move'' ] object`"}},{"id":"d","text":{"en":"`[] class`","uk":"`[] class`"}}]}'::jsonb, null::jsonb),
  ('cls-this-before-super', 'quiz', 2, 60, '{"en":"`this` in a derived constructor","uk":"`this` у похідному конструкторі"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class A {}\nclass B extends A {\n  constructor() {\n    this.x = 1;\n    super();\n  }\n}\ntry {\n  new B();\n} catch (e) {\n  console.log(e.constructor.name);\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`ReferenceError`","uk":"`ReferenceError`"}},{"id":"b","text":{"en":"`TypeError`","uk":"`TypeError`"}},{"id":"c","text":{"en":"`SyntaxError`","uk":"`SyntaxError`"}},{"id":"d","text":{"en":"Nothing; `x` is set to 1","uk":"Нічого; `x` отримує значення 1"}}]}'::jsonb, null::jsonb),
  ('cls-extends-error', 'quiz', 2, 75, '{"en":"Custom errors","uk":"Власні помилки"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class NotFound extends Error {\n  name = \"NotFound\";\n}\nconst e = new NotFound(\"no user\");\nconsole.log(e instanceof Error, e.name, String(e));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`true NotFound NotFound: no user`","uk":"`true NotFound NotFound: no user`"}},{"id":"b","text":{"en":"`true Error Error: no user`","uk":"`true Error Error: no user`"}},{"id":"c","text":{"en":"`false NotFound NotFound: no user`","uk":"`false NotFound NotFound: no user`"}},{"id":"d","text":{"en":"`true NotFound Error: no user`","uk":"`true NotFound Error: no user`"}}]}'::jsonb, null::jsonb),
  ('cls-arrow-field', 'quiz', 3, 90, '{"en":"Arrow-function fields","uk":"Поля-стрілочні функції"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class A {\n  greet = () => \"A\";\n  hello() {\n    return \"hello A\";\n  }\n}\nclass B extends A {\n  hello() {\n    return super.hello() + \"!\";\n  }\n}\nconst b = new B();\nconsole.log(b.hello(), Object.hasOwn(b, \"greet\"), Object.hasOwn(A.prototype, \"greet\"));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`hello A! true false`","uk":"`hello A! true false`"}},{"id":"b","text":{"en":"`hello A! false true`","uk":"`hello A! false true`"}},{"id":"c","text":{"en":"`hello A! true true`","uk":"`hello A! true true`"}},{"id":"d","text":{"en":"A `TypeError` from `super.hello`","uk":"`TypeError` через `super.hello`"}}]}'::jsonb, null::jsonb),
  ('cls-static-inheritance', 'quiz', 3, 90, '{"en":"Static members and `this`","uk":"Статичні члени й `this`"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class Model {\n  static table = \"models\";\n  static create() {\n    return new this();\n  }\n}\nclass User extends Model {}\nconsole.log(User.create() instanceof User, User.table, Object.getPrototypeOf(User) === Model);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`true models true`","uk":"`true models true`"}},{"id":"b","text":{"en":"`false models true`","uk":"`false models true`"}},{"id":"c","text":{"en":"`true undefined false`","uk":"`true undefined false`"}},{"id":"d","text":{"en":"`false undefined true`","uk":"`false undefined true`"}}]}'::jsonb, null::jsonb),
  ('cls-private-brand-check', 'quiz', 3, 90, '{"en":"Private fields and brand checks","uk":"Приватні поля й перевірка бренду"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class Point {\n  #x = 1;\n  static isPoint(o) {\n    return #x in o;\n  }\n  getX() {\n    return this.#x;\n  }\n}\nconst fake = Object.create(Point.prototype);\nconst out = [Point.isPoint(new Point()), Point.isPoint(fake)];\ntry {\n  out.push(fake.getX());\n} catch (e) {\n  out.push(e.constructor.name);\n}\nconsole.log(out);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ true, false, ''TypeError'' ]`","uk":"`[ true, false, ''TypeError'' ]`"}},{"id":"b","text":{"en":"`[ true, true, 1 ]`","uk":"`[ true, true, 1 ]`"}},{"id":"c","text":{"en":"`[ true, false, undefined ]`","uk":"`[ true, false, undefined ]`"}},{"id":"d","text":{"en":"`[ true, true, ''TypeError'' ]`","uk":"`[ true, true, ''TypeError'' ]`"}}]}'::jsonb, null::jsonb),
  ('cls-init-order', 'quiz', 4, 120, '{"en":"A base constructor calling an overridden method","uk":"Базовий конструктор викликає перевизначений метод"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class Base {\n  constructor() {\n    this.describe();\n  }\n  describe() {\n    console.log(\"base\");\n  }\n}\nclass Child extends Base {\n  label = \"child\";\n  describe() {\n    console.log(\"label:\", this.label);\n  }\n}\nnew Child();","codeLanguage":"js","options":[{"id":"a","text":{"en":"`label: undefined`","uk":"`label: undefined`"}},{"id":"b","text":{"en":"`label: child`","uk":"`label: child`"}},{"id":"c","text":{"en":"`base`","uk":"`base`"}},{"id":"d","text":{"en":"A `ReferenceError`: `this` isn''t ready","uk":"`ReferenceError`: `this` ще не готовий"}}]}'::jsonb, null::jsonb),
  ('cls-field-define-semantics', 'quiz', 4, 120, '{"en":"A field with the same name as an inherited setter","uk":"Поле з тим самим ім''ям, що й успадкований сетер"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class A {\n  set value(v) {\n    console.log(\"setter\", v);\n  }\n}\nclass B extends A {\n  value = 1;\n}\nconsole.log(Object.keys(new B()));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''value'' ]`","uk":"`[ ''value'' ]`"}},{"id":"b","text":{"en":"`setter 1` and then `[]`","uk":"`setter 1`, а потім `[]`"}},{"id":"c","text":{"en":"`setter 1` and then `[ ''value'' ]`","uk":"`setter 1`, а потім `[ ''value'' ]`"}},{"id":"d","text":{"en":"`[]`","uk":"`[]`"}}]}'::jsonb, null::jsonb),
  ('cls-array-subclass', 'quiz', 4, 120, '{"en":"Subclassing `Array`","uk":"Наслідування `Array`"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class Stack extends Array {\n  peek() {\n    return this.at(-1);\n  }\n}\nconst s = Stack.from([1, 2, 3]);\nconst evens = s.filter((n) => n % 2);\nconsole.log(evens instanceof Stack, evens.peek(), s.length);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`true 3 3`","uk":"`true 3 3`"}},{"id":"b","text":{"en":"`false 3 3`","uk":"`false 3 3`"}},{"id":"c","text":{"en":"`true 2 3`","uk":"`true 2 3`"}},{"id":"d","text":{"en":"A `TypeError`: `peek` isn''t a function","uk":"`TypeError`: `peek` не є функцією"}}]}'::jsonb, null::jsonb),
  ('cls-private-proxy', 'quiz', 5, 150, '{"en":"Proxies and `#private`","uk":"Proxy і `#private`"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-classes', '{"mode":"single","code":"class Counter {\n  #n = 0;\n  inc() {\n    return ++this.#n;\n  }\n}\nconst c = new Proxy(new Counter(), {});\ntry {\n  console.log(c.inc());\n} catch (e) {\n  console.log(e.constructor.name);\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`TypeError`","uk":"`TypeError`"}},{"id":"b","text":{"en":"`1`","uk":"`1`"}},{"id":"c","text":{"en":"`NaN`","uk":"`NaN`"}},{"id":"d","text":{"en":"`undefined`","uk":"`undefined`"}}]}'::jsonb, null::jsonb),
  ('cls-mixins', 'practice', 4, 1500, '{"en":"Composable class mixins","uk":"Компоновані міксини класів"}'::jsonb, '{"en":"A mixin is a function that takes a class and returns a subclass of it: `class User extends Serializable(Observable(Timestamped(Model))) {}`. Implement the following in `src/mixins.ts`:\n\n- `Timestamped`: `createdAt` and `updatedAt` fields set from `Date.now()`, and `touch()`, which updates `updatedAt` and returns `this`.\n- `Observable`: `on(event, fn)` returns an unsubscribe function, and `emit(event, payload)` calls the listeners. The listeners must be **private**, so they don''t appear in `Object.keys` or JSON.\n- `Serializable`:\n  - `toJSON()` returns `{ type: <class name>, ...own data fields }`.\n  - `static fromJSON(json)` returns an instance of **the class it''s called on** with the data copied in, without the `type` key.\n- `defineMixin(factory)` wraps a factory, and `hasMixin(obj, mixin)` says whether an object''s class chain includes a class that mixin produced.\n\nThe base class must keep working, constructor arguments must pass through, and subclasses must be able to override methods and call `super`.","uk":"Міксин є функцією, що приймає клас і повертає його підклас: `class User extends Serializable(Observable(Timestamped(Model))) {}`. Реалізуйте в `src/mixins.ts` таке:\n\n- `Timestamped`: поля `createdAt` і `updatedAt` зі значенням `Date.now()` і `touch()`, що оновлює `updatedAt` і повертає `this`.\n- `Observable`: `on(event, fn)` повертає функцію відписки, а `emit(event, payload)` викликає слухачів. Слухачі мають бути **приватними**, тож вони не з''являються в `Object.keys` чи JSON.\n- `Serializable`:\n  - `toJSON()` повертає `{ type: <назва класу>, ...власні поля даних }`.\n  - `static fromJSON(json)` повертає екземпляр **класу, на якому його викликали**, зі скопійованими даними, без ключа `type`.\n- `defineMixin(factory)` загортає фабрику, а `hasMixin(obj, mixin)` каже, чи включає ланцюжок класів об''єкта клас, створений цим міксином.\n\nБазовий клас має й далі працювати, аргументи конструктора мають проходити далі, а підкласи мають могти перевизначати методи й викликати `super`."}'::jsonb, 'js-classes', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/mixins.ts":"export type Ctor<T = object> = new (...args: any[]) => T;\n\n/** Wraps a mixin factory so hasMixin can recognise the classes it produces. */\nexport function defineMixin<F extends (Base: Ctor) => Ctor>(factory: F): F {\n  // TODO\n  return factory;\n}\n\n/** True if obj''s class chain includes a class produced by mixin. */\nexport function hasMixin(obj: unknown, mixin: Function): boolean {\n  // TODO\n  return false;\n}\n\n/** Adds createdAt / updatedAt (from Date.now()) and touch(). */\nexport const Timestamped = defineMixin(<B extends Ctor>(Base: B) => class extends Base {\n  // TODO\n});\n\n/** Adds on(event, fn) → unsubscribe, and emit(event, payload). Listeners must stay private. */\nexport const Observable = defineMixin(<B extends Ctor>(Base: B) => class extends Base {\n  // TODO\n});\n\n/** Adds toJSON() → { type: class name, ...data fields } and static fromJSON(json). */\nexport const Serializable = defineMixin(<B extends Ctor>(Base: B) => class extends Base {\n  // TODO\n});\n","/index.ts":"import \"./styles.css\";\nimport { Observable, Serializable, Timestamped, hasMixin } from \"./src/mixins\";\n\nclass Model {\n  id: string;\n  constructor(id = \"none\") {\n    this.id = id;\n  }\n}\nclass User extends Serializable(Observable(Timestamped(Model))) {\n  name = \"anon\";\n}\n\nconst lines: string[] = [];\ntry {\n  const user: any = new User(\"u1\");\n  user.on?.(\"change\", (p: unknown) => lines.push(\"change: \" + JSON.stringify(p)));\n  user.name = \"Ada\";\n  user.emit?.(\"change\", { name: \"Ada\" });\n  lines.push(JSON.stringify(user));\n  lines.push(\"observable? \" + hasMixin(user, Observable));\n} catch (e) {\n  lines.push(\"error: \" + (e as Error).message);\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Mixins</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/mixins.ts","/index.ts"],"activeFile":"/src/mixins.ts","tests":"import { describe, it, expect, fn } from \"./test-kit\";\nimport { Observable, Serializable, Timestamped, defineMixin, hasMixin } from \"../src/mixins\";\n\nclass Model {\n  constructor(id = \"none\") {\n    this.id = id;\n  }\n  describe() {\n    return \"model \" + this.id;\n  }\n}\nclass User extends Serializable(Observable(Timestamped(Model))) {\n  name = \"anon\";\n  rename(name) {\n    this.name = name;\n    this.touch();\n    this.emit(\"change\", { name });\n    return this;\n  }\n}\n\nfunction atTime(t, run) {\n  const realNow = Date.now;\n  Date.now = () => t.now;\n  try {\n    return run();\n  } finally {\n    Date.now = realNow;\n  }\n}\n\ndescribe(\"mixins\", () => {\n  it(\"keep the base class working\", () => {\n    const u = new User(\"u1\");\n    expect(u.id).toBe(\"u1\");\n    expect(u).toBeInstanceOf(Model);\n    expect(u.describe()).toBe(\"model u1\");\n  });\n  it(\"Timestamped records creation and update times\", () => {\n    const t = { now: 1000 };\n    atTime(t, () => {\n      const u = new User(\"u1\");\n      expect(u.createdAt).toBe(1000);\n      expect(u.updatedAt).toBe(1000);\n      t.now = 2500;\n      expect(u.touch()).toBe(u);\n      expect(u.updatedAt).toBe(2500);\n      expect(u.createdAt).toBe(1000);\n    });\n  });\n  it(\"Observable emits events and supports unsubscribing\", () => {\n    const u = new User(\"u1\");\n    const onChange = fn();\n    const off = u.on(\"change\", onChange);\n    u.rename(\"Ada\");\n    expect(onChange).toHaveBeenCalledWith({ name: \"Ada\" });\n    off();\n    u.rename(\"Bob\");\n    expect(onChange).toHaveBeenCalledTimes(1);\n  });\n  it(\"keeps listeners private\", () => {\n    const u = new User(\"u1\");\n    u.on(\"change\", () => {});\n    expect(Object.keys(u)).toEqual([\"id\", \"createdAt\", \"updatedAt\", \"name\"]);\n  });\n  it(\"Serializable produces JSON with the class name\", () => {\n    atTime({ now: 7 }, () => {\n      const u = new User(\"u1\").rename(\"Ada\");\n      expect(JSON.parse(JSON.stringify(u))).toEqual({ type: \"User\", id: \"u1\", createdAt: 7, updatedAt: 7, name: \"Ada\" });\n    });\n  });\n  it(\"fromJSON restores an instance of the class it''s called on\", () => {\n    const copy = User.fromJSON({ type: \"User\", id: \"u2\", name: \"Bob\", createdAt: 5, updatedAt: 6 });\n    expect(copy).toBeInstanceOf(User);\n    expect(copy.name).toBe(\"Bob\");\n    expect(copy.createdAt).toBe(5);\n    expect(copy.type).toBeUndefined();\n    expect(copy.rename(\"Bo\").name).toBe(\"Bo\");\n  });\n  it(\"works with subclasses and super\", () => {\n    class Admin extends User {\n      touches = 0;\n      touch() {\n        this.touches++;\n        return super.touch();\n      }\n    }\n    const admin = new Admin(\"a1\").rename(\"Root\");\n    expect(admin.touches).toBe(1);\n    expect(admin.toJSON().type).toBe(\"Admin\");\n    expect(Admin.fromJSON({ id: \"a2\" })).toBeInstanceOf(Admin);\n  });\n  it(\"hasMixin recognises classes built from a mixin\", () => {\n    const Tagged = defineMixin((Base) => class extends Base { tags = []; });\n    class Post extends Tagged(Model) {}\n    expect(hasMixin(new User(), Observable)).toBe(true);\n    expect(hasMixin(new User(), Timestamped)).toBe(true);\n    expect(hasMixin(new Post(), Tagged)).toBe(true);\n    expect(hasMixin(new Post(), Observable)).toBe(false);\n    expect(hasMixin(new Model(), Tagged)).toBe(false);\n    expect(hasMixin(null, Tagged)).toBe(false);\n  });\n});\n","testCount":8}'::jsonb),
  ('cls-shape-registry', 'practice', 3, 1200, '{"en":"An abstract class with a self-registering hierarchy","uk":"Абстрактний клас з ієрархією, що реєструється сама"}'::jsonb, '{"en":"Finish the shape hierarchy in `src/shapes.ts`:\n\n- `Shape` is **abstract**: `new Shape()` throws a `TypeError`, while subclasses can be created. Its default `area` getter throws `\"area is not implemented\"`.\n- `Circle({ radius })` and `Rect({ width, height })` keep their dimensions in **private** fields, exposed through getters and setters that throw a `RangeError` for anything that isn''t a positive finite number (the old value stays).\n- Serialisation: `JSON.stringify(shape)` gives `{\"type\": …, …data}`, where `type` is the class''s static `type`; `Object.keys(shape)` is empty.\n- Registry: subclasses register themselves with `static { Shape.register(this); }`. The registry itself is private. `Shape.types` lists the registered types, and `Shape.from(json)` creates the right class, throwing a `TypeError` for unknown types.\n\nThe tests also define a `Square extends Rect` that registers itself and overrides `data()`.","uk":"Завершіть ієрархію фігур у `src/shapes.ts`:\n\n- `Shape` є **абстрактним**: `new Shape()` кидає `TypeError`, а підкласи створювати можна. Його типовий гетер `area` кидає `\"area is not implemented\"`.\n- `Circle({ radius })` і `Rect({ width, height })` тримають свої розміри в **приватних** полях, доступних через гетери й сетери, що кидають `RangeError` для будь-чого, крім додатного скінченного числа (старе значення зберігається).\n- Серіалізація: `JSON.stringify(shape)` дає `{\"type\": …, …data}`, де `type` є статичним `type` класу; `Object.keys(shape)` порожній.\n- Реєстр: підкласи реєструють себе через `static { Shape.register(this); }`. Сам реєстр приватний. `Shape.types` перелічує зареєстровані типи, а `Shape.from(json)` створює потрібний клас і кидає `TypeError` для невідомих типів.\n\nТести також визначають `Square extends Rect`, що реєструє себе й перевизначає `data()`."}'::jsonb, 'js-classes', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/shapes.ts":"export type ShapeData = { type: string; [key: string]: unknown };\n\nexport class Shape {\n  static type = \"shape\";\n\n  // TODO: make Shape abstract, keep a private registry of subclasses by type,\n  // and implement register / from / types / toJSON.\n  static register(cls: any) {}\n  static from(data: ShapeData): Shape {\n    throw new Error(\"Not implemented\");\n  }\n  static get types(): string[] {\n    return [];\n  }\n\n  get area(): number {\n    return 0;\n  }\n  protected data(): Record<string, unknown> {\n    return {};\n  }\n}\n\nexport class Circle extends Shape {\n  static type = \"circle\";\n  radius: number; // TODO: private, validated\n  constructor({ radius }: { radius: number }) {\n    super();\n    this.radius = radius;\n  }\n  get area() {\n    return Math.PI * this.radius ** 2;\n  }\n}\n\nexport class Rect extends Shape {\n  static type = \"rect\";\n  width: number; // TODO: private, validated\n  height: number;\n  constructor({ width, height }: { width: number; height: number }) {\n    super();\n    this.width = width;\n    this.height = height;\n  }\n  get area() {\n    return this.width * this.height;\n  }\n}\n","/index.ts":"import \"./styles.css\";\nimport { Circle, Rect, Shape } from \"./src/shapes\";\n\nconst lines: string[] = [];\ntry {\n  const shapes: Shape[] = [new Circle({ radius: 1 }), new Rect({ width: 2, height: 3 })];\n  for (const s of shapes) lines.push(JSON.stringify(s) + \" area=\" + s.area.toFixed(2));\n  lines.push(\"registered: \" + Shape.types.join(\", \"));\n  lines.push(\"restored: \" + Shape.from({ type: \"rect\", width: 4, height: 5 }).area);\n} catch (e) {\n  lines.push(\"error: \" + (e as Error).message);\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Shapes</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/shapes.ts","/index.ts"],"activeFile":"/src/shapes.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { Circle, Rect, Shape } from \"../src/shapes\";\n\nclass Square extends Rect {\n  static type = \"square\";\n  static {\n    Shape.register(this);\n  }\n  constructor({ side }) {\n    super({ width: side, height: side });\n  }\n  data() {\n    return { side: this.width };\n  }\n}\n\ndescribe(\"Shape\", () => {\n  it(\"is abstract\", () => {\n    expect(() => new Shape()).toThrow(TypeError);\n    class Blob extends Shape {}\n    const blob = new Blob();\n    expect(blob).toBeInstanceOf(Shape);\n    expect(() => blob.area).toThrow(\"not implemented\");\n  });\n  it(\"computes areas\", () => {\n    expect(new Circle({ radius: 1 }).area).toBeCloseTo(Math.PI);\n    expect(new Rect({ width: 2, height: 3 }).area).toBe(6);\n  });\n  it(\"validates on construction and on assignment\", () => {\n    expect(() => new Circle({ radius: -1 })).toThrow(RangeError);\n    expect(() => new Rect({ width: 2, height: NaN })).toThrow(RangeError);\n    const c = new Circle({ radius: 2 });\n    expect(() => { c.radius = 0; }).toThrow(RangeError);\n    expect(c.radius).toBe(2);\n    c.radius = 3;\n    expect(c.area).toBeCloseTo(9 * Math.PI);\n  });\n  it(\"keeps its state private and serialises with its type\", () => {\n    const c = new Circle({ radius: 2 });\n    expect(Object.keys(c)).toEqual([]);\n    expect(JSON.stringify(c)).toBe(''{\"type\":\"circle\",\"radius\":2}'');\n    expect(JSON.stringify(new Rect({ width: 2, height: 3 }))).toBe(''{\"type\":\"rect\",\"width\":2,\"height\":3}'');\n  });\n  it(\"lets subclasses register themselves\", () => {\n    expect(Shape.types).toContain(\"circle\");\n    expect(Shape.types).toContain(\"rect\");\n    expect(Shape.types).toContain(\"square\");\n    expect(Shape.registry).toBeUndefined();\n  });\n  it(\"creates the right class from JSON\", () => {\n    const rect = Shape.from({ type: \"rect\", width: 2, height: 3 });\n    expect(rect).toBeInstanceOf(Rect);\n    expect(rect.area).toBe(6);\n    const square = Shape.from({ type: \"square\", side: 2 });\n    expect(square).toBeInstanceOf(Square);\n    expect(square).toBeInstanceOf(Rect);\n    expect(square.area).toBe(4);\n    expect(JSON.stringify(square)).toBe(''{\"type\":\"square\",\"side\":2}'');\n    expect(() => Shape.from({ type: \"hexagon\" })).toThrow(TypeError);\n  });\n  it(\"round-trips through JSON\", () => {\n    for (const shape of [new Circle({ radius: 1.5 }), new Rect({ width: 1, height: 4 }), new Square({ side: 3 })]) {\n      const copy = Shape.from(JSON.parse(JSON.stringify(shape)));\n      expect(copy.constructor).toBe(shape.constructor);\n      expect(copy.area).toBeCloseTo(shape.area);\n    }\n  });\n});\n","testCount":7}'::jsonb),
  ('col-same-value-zero', 'quiz', 1, 45, '{"en":"How does a Set compare values?","uk":"Як Set порівнює значення?"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-collections', '{"mode":"single","code":"console.log(new Set([NaN, NaN, 0, -0, \"0\"]).size);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`3`","uk":"`3`"}},{"id":"b","text":{"en":"`5`","uk":"`5`"}},{"id":"c","text":{"en":"`4`","uk":"`4`"}},{"id":"d","text":{"en":"`2`","uk":"`2`"}}]}'::jsonb, null::jsonb),
