rget \" + target);\n        }\n        catch (ArgumentException)\n        {\n            Console.WriteLine(\"bad name\");\n        }\n    }\n\n    static void Main()\n    {\n        var t = new Thermostat(\"Hall\", 20);\n        Console.WriteLine(t.Name + \": \" + t.Target);\n        SetTarget(t, 40);\n        Console.WriteLine(t.Target);\n        SetTarget(t, 5);\n        SetTarget(t, 4);\n        Console.WriteLine(t.Target);\n        Warm(t, 10);\n        Console.WriteLine(t.Target);\n        Warm(t, 30);\n        Console.WriteLine(t.Target);\n        Create(\"Attic\", 99);\n        Create(\"\", 20);\n        Create(\"Attic\", 18);\n    }\n}\n"'::jsonb #>> '{}')),
