  ('csharp', 'ref-practice', null::jsonb, ('"7 3\n14\n0\n2\n8\n8\n"'::jsonb #>> '{}'), ('"using System;\n\nstruct Counter\n{\n    public int Value;\n\n    public void Add(int n)\n    {\n        Value += n;\n    }\n}\n\nclass Program\n{\n    // Exchanges the values of the two variables\n    static void Swap(ref int a, ref int b)\n    {\n        int t = a;\n        a = b;\n        b = t;\n    }\n\n    // Doubles the value of the variable\n    static void Double(ref int x)\n    {\n        x = x * 2;\n    }\n\n    // Sets the Value of the counter to 0\n    static void Reset(ref Counter counter)\n    {\n        counter.Value = 0;\n    }\n\n    static void Main()\n    {\n        int a = 3, b = 7;\n        Swap(ref a, ref b);\n        Console.WriteLine(a + \" \" + b);\n        Double(ref a);\n        Console.WriteLine(a);\n\n        Counter c = new Counter();\n        c.Add(5);\n        Reset(ref c);\n        Console.WriteLine(c.Value);\n        c.Add(2);\n        Console.WriteLine(c.Value);\n\n        int x = 1;\n        Double(ref x);\n        Double(ref x);\n        Double(ref x);\n        Console.WriteLine(x);\n        Swap(ref x, ref x);\n        Console.WriteLine(x);\n    }\n}\n"'::jsonb #>> '{}')),
