  ('csharp', 'brainfuck-vm', null::jsonb, ('"Hello World!\nA\nB\n"'::jsonb #>> '{}'), ('"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\n\n\nclass Program\n{\n    // Runs a Brainfuck program and returns the text it writes\n    static string Run(string program, string input)\n    {\n        byte[] tape = new byte[30000];\n        int pointer = 0;\n        int inputPos = 0;\n        var output = new StringBuilder();\n\n        // Pair up the brackets once: jump[i] is the position of the matching bracket\n        var jump = new int[program.Length];\n        var open = new Stack<int>();\n        for (int i = 0; i < program.Length; i++)\n        {\n            if (program[i] == ''['')\n            {\n                open.Push(i);\n            }\n            else if (program[i] == '']'')\n            {\n                int start = open.Pop();\n                jump[start] = i;\n                jump[i] = start;\n            }\n        }\n\n        for (int pc = 0; pc < program.Length; pc++)\n        {\n            switch (program[pc])\n            {\n                case ''>'':\n                    pointer++;\n                    break;\n                case ''<'':\n                    pointer--;\n                    break;\n                case ''+'':\n                    tape[pointer]++;\n                    break;\n                case ''-'':\n                    tape[pointer]--;\n                    break;\n                case ''.'':\n                    output.Append((char)tape[pointer]);\n                    break;\n                case '','':\n                    tape[pointer] = inputPos < input.Length ? (byte)input[inputPos++] : (byte)0;\n                    break;\n                case ''['':\n                    if (tape[pointer] == 0)\n                    {\n                        pc = jump[pc];\n                    }\n                    break;\n                case '']'':\n                    if (tape[pointer] != 0)\n                  